/* prog25_balanced_multitype.c
 *
 * Checks whether a string contains a correctly balanced sequence of
 * parentheses '()', square brackets '[]' and curly braces '{}'.
 *
 * Usage:
 *   ./prog25_balanced_multitype [string]
 *
 * If no argument is supplied the empty string is examined.
 * The program prints either "BALANCED" or "UNBALANCED" (followed by a
 * newline) and returns 0.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static int is_open(char c)
{
    return c == '(' || c == '[' || c == '{';
}

static char matching_close(char open)
{
    switch (open) {
        case '(': return ')';
        case '[': return ']';
        case '{': return '}';
        default:  return 0;   /* never reached */
    }
}

/* Returns 1 if the string is balanced, 0 otherwise. */
static int check_balanced(const char *s)
{
    size_t len = strlen(s);
    /* The stack never needs to be larger than the input length. */
    char *stack = malloc(len);
    if (!stack) {
        /* In the original binary a memory‑allocation failure would simply
           abort; here we treat it as “unbalanced”. */
        return 0;
    }

    size_t top = 0;          /* points to the next free slot */
    int balanced = 1;        /* flag that stays 1 while everything matches */

    for (size_t i = 0; i < len && balanced; ++i) {
        char c = s[i];
        if (is_open(c)) {
            stack[top++] = c;                /* push */
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) {                  /* nothing to match */
                balanced = 0;
                break;
            }
            char open = stack[--top];        /* pop */
            if (c != matching_close(open)) {
                balanced = 0;
                break;
            }
        }
        /* All other characters are ignored – this matches the original. */
    }

    /* If there are still items on the stack the string is not balanced. */
    if (top != 0)
        balanced = 0;

    free(stack);
    return balanced;
}

int main(int argc, char **argv)
{
    const char *input = (argc > 1) ? argv[1] : "";
    if (check_balanced(input))
        puts("BALANCED");
    else
        puts("UNBALANCED");
    return 0;
}
